def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dicts; treats lists and other
    values atomically. If an entire key is added or removed, only that
    parent path is reported.
    """
    paths = set()
    all_keys = set(before.keys()) | set(after.keys())

    for key in all_keys:
        path = str(key)

        if key in before and key in after:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                for sub_path in changed_paths(b_val, a_val):
                    paths.add(f"{path}.{sub_path}")
            else:
                if b_val != a_val:
                    paths.add(path)
        elif key in before:
            paths.add(path)
        else:
            paths.add(path)

    return sorted(paths)
```

