def unique_latest(records):
    first_appearance = []
    best = {}
    seen = set()

    for record in records:
        rid = record['id']
        if rid not in seen:
            seen.add(rid)
            first_appearance.append(rid)
        if rid not in best or record['timestamp'] >= best[rid]['timestamp']:
            best[rid] = record

    return [best[rid] for rid in first_appearance]
