def normalize(path):
    """Normalize an absolute POSIX-like path.

    - Collapses repeated '/'
    - Ignores '.' components
    - Resolves '..' without going above root
    - Returns '/' for root
    - Never has a trailing slash (except root)

    Raises ValueError if the path is not absolute.
    """
    if not isinstance(path, str) or not path.startswith('/'):
        raise ValueError(f"path is not absolute: {path!r}")

    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

