import heapq


def order(deps):
    # Build the full set of nodes (keys + all prerequisites)
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Compute in-degrees (number of prerequisites for each node)
    in_degree = {node: 0 for node in nodes}
    for node, prereqs in deps.items():
        in_degree[node] = len(set(prereqs))

    # Build reverse adjacency: for each node, which nodes depend on it
    dependents = {node: [] for node in nodes}
    for node, prereqs in deps.items():
        for p in set(prereqs):
            dependents[p].append(node)

    # Min-heap of ready nodes (in-degree 0)
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result
```

